// 走棋音效：用 WebAudio 合成木頭棋子的「叩」聲（吃子比較重），設定裡可以關
let AC=null;
// iPhone 主畫面 App 的聲音（rootcause：切到背景／鎖螢幕回來後，AudioContext 常常顯示 running 但其實已經不出聲，resume 也救不回來）
// 作法：1. 一進背景就把舊的 AudioContext 關掉丟掉，回來後下一次點選重新建一個（一定要在點選裡建才會被 iOS 允許出聲）
//       2. 每次點選檢查時間有沒有在走：顯示 running 但 currentTime 停住＝壞掉了，也重建
//       3. 新建後播一個無聲片段解鎖；audioSession 設 playback，靜音鍵打開也有聲音
const newAC=()=>{try{if(AC)AC.close()}catch(e){}AC=null;try{const C=window.AudioContext||window.webkitAudioContext;if(C){AC=new C();AC._t=performance.now();AC._ct=0}}catch(e){}};
const unlockAudio=()=>{primeVoice();try{if(navigator.audioSession&&navigator.audioSession.type!=="playback")navigator.audioSession.type="playback"}catch(e){}
  try{const now=performance.now();
    if(!AC||AC.state==="closed")newAC();
    else if(AC.state==="running"&&AC.currentTime===AC._ct&&now-AC._t>800)newAC();   // 時間停住了：殭屍狀態
    if(!AC)return;AC._t=now;AC._ct=AC.currentTime;
    if(AC.state!=="running"){const p=AC.resume();if(p&&p.catch)p.catch(()=>{})}
    if(!AC._primed){const b=AC.createBuffer(1,1,22050),src=AC.createBufferSource();src.buffer=b;src.connect(AC.destination);src.start(0);AC._primed=1}}catch(e){}};
const sndOn=()=>{try{return!sxmAllOff()&&(store.get("capSound",true)||store.get("mvSound",false)||store.get("voiceCall",true))}catch(e){return false}};   /* 第 6 輪 F3：全部靜音時不跳「點任意處喚醒聲音」 */
function sndPill(show){let p=document.getElementById("sndPill");if(!show){if(p)p.remove();return}if(p||!sndOn())return;
  p=document.createElement("div");p.id="sndPill";p.textContent="🔇 點任意處喚醒聲音";document.body.append(p);setTimeout(()=>{if(p.isConnected)p.remove()},8000);
  sndPillAt();setTimeout(sndPillAt,300);setTimeout(sndPillAt,1500)}
/* v5 改善單 R07（聲音提示避讓）：頂欄下置中的位置在對局頁正好壓在對手（黑方）那一條上——直式蓋到對手名字，橫放（左棋盤、右資訊欄）蓋到右欄最上面的黑方資訊。
   對局頁（有 gameLayout 的 #pTop）才挪：依序試 ①原位置 ②工具列正下方（橫放時右欄工具列下面那片空白）③工具列正上方（直式時狀態列和工具列之間的空白）
   ④棋盤左邊空白 ⑤棋盤右邊空白 ⑥狀態列下方 ⑦右下角；第一個完全不碰頂欄、雙方資訊、棋盤、狀態、著法條、工具列、小帥的就用它，都碰到就挑碰到面積最小的。
   其他頁照舊在頂欄下置中。換頁、轉向時重算（提示只活 8 秒） */
function sndPillAt(sm){const p=document.getElementById("sndPill");if(!p)return;p.style.left="";p.style.top="";p.style.transform="";
  if(!sm)Object.assign(p.style,{padding:"",fontSize:""});
  if(!document.getElementById("pTop"))return;
  const r=p.getBoundingClientRect(),w=r.width,h=r.height,vw=innerWidth,vh=innerHeight,m=8;if(!w||!h)return;
  const R=s=>{const e=document.querySelector(s);if(!e||!e.getClientRects().length)return null;const b=e.getBoundingClientRect();return b.width>1&&b.height>1?b:null};
  const ob=["#topbar","#pTop","#pBot","#bbox","#stat","#strip",".evline","#acts",".xqbot"].map(R).filter(Boolean),A=R("#acts"),Bx=R("#bbox"),S=R("#stat");
  const C=[[r.left,r.top]];if(A){const x=A.left+A.width/2-w/2;C.push([x,A.bottom+8],[x,A.top-h-8])}
  if(Bx)C.push([(Bx.left-w)/2,Bx.top+8],[Bx.right+(vw-Bx.right-w)/2,Bx.top+8]);if(S)C.push([S.left+S.width/2-w/2,S.bottom+8]);C.push([vw-w-12,vh-h-12]);
  for(const b of ob){const y=b.bottom+4;C.push([vw/2-w/2,y],[m,y],[vw-w-m,y])}
  const cost=([x,y])=>{if(x<m||y<m||x+w>vw-m||y+h>vh-m)return 1e12;let c=0;for(const b of ob){const ix=Math.min(x+w,b.right+4)-Math.max(x,b.left-4),iy=Math.min(y+h,b.bottom+4)-Math.max(y,b.top-4);if(ix>0&&iy>0)c+=ix*iy}return c};
  let best=C[0],bc=Infinity;for(const c of C){const k=cost(c);if(k<bc){bc=k;best=c}if(k===0)break}
  if(bc>0&&!sm){Object.assign(p.style,{padding:"2px 9px",fontSize:"11px"});return sndPillAt(1)}
  if(best!==C[0])Object.assign(p.style,{left:Math.round(best[0])+"px",top:Math.round(best[1])+"px",transform:"none"})}
addEventListener("resize",()=>setTimeout(sndPillAt,200));addEventListener("hashchange",()=>{setTimeout(sndPillAt,400);setTimeout(sndPillAt,1500)});
  /* 開發者 11/11 選 ChatGPT UI 報告 UI-05：聲音提示原本一直閃在右下角，蓋在設定、首頁底部按鈕和小帥上；改成頂欄正下方置中、不閃，8 秒後自己收起（點任何地方也會收起） */
  (()=>{try{const s=document.createElement("style");s.id="sndPillPos";s.textContent="#sndPill{right:auto!important;bottom:auto!important;left:50%;top:calc(env(safe-area-inset-top,0px) + 64px);transform:translateX(-50%);animation:none!important;opacity:.9;font-size:12.5px}";document.head.append(s)}catch(e){}})();
