function bgmList(){return BGM.list||(BGM.list=fetch("data/bgm/index.json").then(r=>r.ok?r.json():{}).catch(()=>({}))).then(j=>{BGM.L=j;return j})}
/* 意見回饋 687：iPhone 只准在點選的當下開始播放；清單已經載好就不要 await，直接同步呼叫 play()，免得等下載完那一下點選已經「過期」
   11/10 開發者「網頁版還是沒有 bgm」：mp3 只放 CDN（GitHub 上 404），而 CDN 不支援分段下載（Range 回 200 整檔），iPhone 的 audio 一定要分段才肯播（media 錯誤 4）。
   改成先把整首抓成 Blob、給播放器 blob: 網址（不用伺服器支援分段）；網頁版直接向 CDN 要，本機和其他網址照原路徑（fetch 404 會自己轉 CDN）。
   清單一載好就先選好曲子、預先下載，第一次點畫面時已經下載好，就能在點選當下同步播放；還沒下載好就等好了再播，iPhone 不准的話下一次點畫面會播 */
const BGM_BASE=/\.github\.io$/.test(location.hostname)?XQ_CDN:"";
function bgmBlob(rel){const U=BGM.u||(BGM.u={});if(U[rel])return Promise.resolve(U[rel]);
  return U[rel]=fetch(BGM_BASE+rel,BGM_BASE?{mode:"cors",credentials:"omit"}:undefined).then(r=>{if(!r.ok)throw new Error("http"+r.status);return r.blob()}).then(b=>U[rel]=URL.createObjectURL(b)).catch(e=>{delete U[rel];BGM.err="下載"+((e&&e.message)||"");return null})}
function bgmPick(era,L,next){if(!next&&BGM.era===era&&BGM.src)return;BGM.era=era;let n=Math.floor(Math.random()*L.length);if(L.length>1&&n===BGM.last)n=(n+1)%L.length;BGM.last=n;BGM.src=`data/bgm/${era}/${L[n]}`;
  const U=BGM.u||{};for(const k of Object.keys(U))if(k!==BGM.src&&typeof U[k]==="string"&&U[k]!==BGM.cur){try{URL.revokeObjectURL(U[k])}catch(e){}delete U[k]}bgmBlob(BGM.src)}
async function bgmSync(next){if(typeof OP!=="undefined"&&OP.on){if(BGM.a)BGM.a.pause();return}   /* 開場配樂（07bh OP）播的時候一般配樂暫停 */
  const on=!!store.get("bgm",true)&&!document.hidden&&sxmGain("bgm")>0,era=BGM.force?"blackhole":store.get("era","classic");   /* 第 6 輪 F3：背景音樂音量 0、靜音、全部靜音＝暫停 */
  if(!on){if(BGM.a)BGM.a.pause();return}const L=BGM.force?[BGM.force]:((BGM.L||await bgmList())||{})[era]||[];if(!L.length){if(BGM.a)BGM.a.pause();return}
  if(!BGM.a){BGM.a=new Audio();BGM.a.volume=sxmBgmVol(sxmMix());BGM.a.preload="auto";BGM.cur="";BGM.a.onended=()=>bgmSync(true);BGM.a.onplay=BGM.a.onpause=()=>bgmNow();BGM.a.onerror=()=>{const x=BGM.a&&BGM.a.error;BGM.err="media"+(x?x.code:"")}}
  bgmPick(era,L,next);const u=(BGM.u||{})[BGM.src];
  if(typeof u!=="string"){const want=BGM.src;bgmBlob(want).then(x=>{if(x&&BGM.src===want&&store.get("bgm",true))bgmSync()});return}
  if(BGM.cur!==u){const old=BGM.cur;BGM.cur=u;BGM.a.src=u;if(old&&old!==u&&!Object.values(BGM.u||{}).includes(old)){try{URL.revokeObjectURL(old)}catch(e){}}}
  if(BGM.a.paused){BGM.tries=(BGM.tries||0)+1;try{const p=BGM.a.play();if(p&&p.then)p.then(()=>{BGM.err="";BGM.ok=(BGM.ok||0)+1;if(!BGM.hint&&!store.get("bgmHint",false)){BGM.hint=1;try{store.set("bgmHint",true)}catch(e){}try{toast("♪ 背景音樂已開始播放，可到設定→聲音調整")}catch(e){}}},e=>{BGM.err=(e&&e.name)||"err"})}catch(e){BGM.err="throw"}}}
/* 意見回饋 689：iPhone 還是沒背景音樂，回饋單（開發者）和設定 → 聲音附上播放器狀態，才知道卡在哪一步 */
function bgmDiag(){try{const a=BGM.a,L=(BGM.L||{})[store.get("era","classic")]||[];return`bgm:${store.get("bgm",true)?"開":"關"}/${store.get("era","classic")}/清單${BGM.L?L.length:"未載"}/${a?(a.paused?"停":"播")+"/rs"+a.readyState+"/ns"+a.networkState+"/t"+(a.currentTime||0).toFixed(1):"無播放器"}/檔${typeof (BGM.u||{})[BGM.src]==="string"?"好":BGM.src?"載":"無"}${BGM_BASE?"CDN":"本站"}/試${BGM.tries||0}成${BGM.ok||0}${BGM.err?"/錯"+BGM.err:""}/AC:${typeof AC!=="undefined"&&AC?AC.state:"無"}/sess:${navigator.audioSession?navigator.audioSession.type:"無"}/sw:${navigator.serviceWorker&&navigator.serviceWorker.controller?"有":"無"}`}catch(e){return"bgm:診斷失敗"}}
