function brushD(P,jit){const S=[],n0=P.length,f=v=>v.toFixed(2);
  for(let i=0;i<n0-1;i++){const p0=P[Math.max(0,i-1)],p1=P[i],p2=P[i+1],p3=P[Math.min(n0-1,i+2)];
    for(let k=0;k<6;k++){const t=k/6,t2=t*t,t3=t2*t,cr=j=>.5*(2*p1[j]+(p2[j]-p0[j])*t+(2*p0[j]-5*p1[j]+4*p2[j]-p3[j])*t2+(3*p1[j]-p0[j]-3*p2[j]+p3[j])*t3);
      S.push([cr(0),cr(1),p1[2]+(p2[2]-p1[2])*t*t*(3-2*t)])}}
  S.push(P[n0-1].slice());
  const n=S.length,Lp=[],Rp=[],N=[];let tx=1,ty=0,sx=1,sy=0;
  for(let i=0;i<n;i++){const a=S[Math.max(0,i-1)],b=S[Math.min(n-1,i+1)];let dx=b[0]-a[0],dy=b[1]-a[1];const l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;
    if(i===0){sx=dx;sy=dy}tx=dx;ty=dy;N.push([-dy,dx]);
    const h=S[i][2]/2,j1=1+(Math.random()-.5)*jit,j2=1+(Math.random()-.5)*jit;
    Lp.push([S[i][0]-dy*h*j1,S[i][1]+dx*h*j1]);Rp.push([S[i][0]+dy*h*j2,S[i][1]-dx*h*j2])}
  // 收筆圓頭（向前）與起筆圓頭（向後）
  const cap=(c,h,nx,ny,fx,fy)=>{const o=[];for(let k=1;k<6;k++){const a=k*Math.PI/6;o.push([c[0]+h*(Math.cos(a)*nx+Math.sin(a)*fx),c[1]+h*(Math.cos(a)*ny+Math.sin(a)*fy)])}return o};
  const e=S[n-1],s=S[0],pts=[...Lp,...cap(e,e[2]/2,-ty,tx,tx,ty),...Rp.reverse(),...cap(s,s[2]/2,sy,-sx,-sx,-sy)];
  return{d:"M"+pts.map(p=>f(p[0])+" "+f(p[1])).join("L")+"Z",S,N}}
